import pandas as pd
import seaborn as sns
import numpy as np
import ast
def task_func(csv_file):
    df = pd.read_csv(csv_file)

    if "email" not in df.columns or "list" not in df.columns:
        raise ValueError("CSV file must contain 'email' and 'list' columns.")

    def parse_numeric_list(value):
        if isinstance(value, list):
            parsed = value
        elif pd.isna(value):
            parsed = []
        elif isinstance(value, str):
            value = value.strip()
            if not value:
                parsed = []
            else:
                parsed = ast.literal_eval(value)
        else:
            parsed = value

        if not isinstance(parsed, (list, tuple, np.ndarray, pd.Series)):
            raise ValueError(f"List column value must parse to a list-like object: {value!r}")

        result = []
        for item in parsed:
            if pd.isna(item):
                continue
            try:
                result.append(float(item))
            except (TypeError, ValueError) as exc:
                raise ValueError(f"List contains a non-numeric value: {item!r}") from exc
        return result

    result = df[["email", "list"]].copy()
    result["list"] = result["list"].apply(parse_numeric_list)
    result["sum"] = result["list"].apply(lambda x: float(np.sum(x)) if len(x) else 0.0)
    result["mean"] = result["list"].apply(lambda x: float(np.mean(x)) if len(x) else np.nan)
    result["std"] = result["list"].apply(lambda x: float(np.std(x)) if len(x) else np.nan)

    ax = sns.histplot(data=result, x="mean")

    return result, ax
